// Map each verified GSC property to a venture slug. Specific subdomains first,
// then domain-property fallbacks. Unmapped properties are skipped.
const resp = $('GSC sites').first().json;
const list = Array.isArray(resp && resp.siteEntry) ? resp.siteEntry : [];
const map = [
  { needle: 'ctrl.themindmaker', product: 'mm_ctrl' },
  { needle: 'pulse.fractionl', product: 'fractionl_pulse' },
  { needle: 'legibility', product: 'legibility' },
  { needle: 'onplinth', product: 'legibility' },
  { needle: 'legibility', product: 'legibility' },
  { needle: 'full-time', product: 'full_time' },
  { needle: 'fulltime', product: 'full_time' },
  { needle: 'themindmaker', product: 'mm_ctrl' },
  { needle: 'fractionl', product: 'fractionl_pulse' },
];
// GSC data lags ~2-3 days; pull a 28-day window ending 3 days back.
const end = new Date(Date.now() - 3 * 86400000).toISOString().slice(0, 10);
const start = new Date(Date.now() - 31 * 86400000).toISOString().slice(0, 10);
const out = [];
for (const s of list) {
  const url = String(s.siteUrl || '').toLowerCase();
  const m = map.find(x => url.includes(x.needle));
  if (!m) continue;
  out.push({ json: { siteUrl: s.siteUrl, product: m.product, startDate: start, endDate: end } });
}
return out;

// Pair each site's response with its product; dedup (product, query) across
// overlapping properties (a domain property and its subdomain both map to one
// venture) by summing clicks/impressions and impression-weighting position.
const plans = $('Plan queries').all().map(i => i.json);
const responses = $('GSC query').all().map(i => i.json);
const nowIso = new Date().toISOString();
const acc = {};
responses.forEach((resp, idx) => {
  const p = plans[idx] || {};
  if (!p.product) return;
  const grows = Array.isArray(resp && resp.rows) ? resp.rows : [];
  for (const r of grows) {
    const q = Array.isArray(r.keys) ? String(r.keys[0] || '') : '';
    if (!q) continue;
    const key = p.product + '||' + q;
    const clicks = Number(r.clicks) || 0;
    const impr = Number(r.impressions) || 0;
    const pos = r.position != null ? Number(r.position) : null;
    const w = impr || 1;
    if (!acc[key]) acc[key] = { product: p.product, query: q, clicks: 0, impressions: 0, posSum: 0, posW: 0 };
    const a = acc[key];
    a.clicks += clicks;
    a.impressions += impr;
    if (pos != null) { a.posSum += pos * w; a.posW += w; }
  }
});
const rows = Object.keys(acc).map(k => {
  const a = acc[k];
  return {
    product: a.product,
    query: a.query,
    clicks: Math.round(a.clicks),
    impressions: Math.round(a.impressions),
    ctr: a.impressions > 0 ? Number((a.clicks / a.impressions).toFixed(4)) : 0,
    current_position: a.posW > 0 ? Number((a.posSum / a.posW).toFixed(1)) : null,
    last_checked_at: nowIso,
  };
});
const striking = rows.filter(r => r.current_position != null && r.current_position >= 4 && r.current_position <= 20).length;
return [{ json: { rows, n: rows.length, striking } }];
